import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        String ip = st.nextToken();
        long count = Long.parseLong(st.nextToken());
        long start = 0;
        for (String part : ip.split("\\.")) start = start * 256 + Long.parseLong(part);
        List<String> out = new ArrayList<>();
        while (count > 0) {
            // Largest block aligned at start (start 0 allows 2^32) that does not exceed the rest.
            long align = start != 0 ? (start & -start) : (1L << 32);
            long size = Math.min(align, Long.highestOneBit(count));
            String addr = ((start >> 24) & 255) + "." + ((start >> 16) & 255) + "." + ((start >> 8) & 255) + "."
                    + (start & 255);
            out.add(addr + "/" + (32 - Long.numberOfTrailingZeros(size)));
            start += size;
            count -= size;
        }
        StringBuilder sb = new StringBuilder();
        sb.append(out.size()).append('\n');
        for (String s : out) sb.append(s).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"fmt"
	"math/bits"
	"strconv"
	"strings"
)

func main() {
	var ip string
	var count uint64
	fmt.Scan(&ip, &count)
	var start uint64
	for _, part := range strings.Split(ip, ".") {
		v, _ := strconv.ParseUint(part, 10, 64)
		start = start*256 + v
	}
	out := []string{}
	for count > 0 {
		// Largest block aligned at start (start 0 allows 2^32) that does not exceed the rest.
		align := uint64(1) << 32
		if start != 0 {
			align = start & -start
		}
		size := min(align, uint64(1)<<(bits.Len64(count)-1))
		addr := fmt.Sprintf("%d.%d.%d.%d", (start>>24)&255, (start>>16)&255, (start>>8)&255, start&255)
		out = append(out, fmt.Sprintf("%s/%d", addr, 32-bits.TrailingZeros64(size)))
		start += size
		count -= size
	}
	fmt.Println(len(out))
	for _, s := range out {
		fmt.Println(s)
	}
}
